    aWandererJ = 0xAD4F19592BE4A4F5ULL;
    aWandererK = 0xE2FAF21696720C7FULL;

    //
    TwistExpander_Bellatrix_Arx::SEED_A(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::SEED_B(PARAMS_SEED);

    TwistExpander_Bellatrix_Arx::SEED_C(PARAMS_SEED);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
